/* Bundled 3270 font, license: assets/3270-LICENSE.txt. No resource fetch. */
window.denpaFontReady=(async()=>{const data=atob('');const bytes=new Uint8Array(data.length);for(let i=0;i<data.length;i++)bytes[i]=data.charCodeAt(i);const face=await new FontFace('IBM3270',bytes,{weight:'400',style:'normal'}).load();document.fonts.add(face);return face;})();window.denpaFontReady.catch(()=>{});
